import { index, int, primaryKey, real, sqliteTable, text } from 'drizzle-orm/sqlite-core';
import { z } from 'zod';

// --- CSV parsing helpers -------------------------------------------------
// The seed CSVs store everything as strings, so these coerce the raw values.

/** "" -> null, otherwise a Date. */
const csvDate = z.preprocess((val) => (val === '' ? null : val), z.coerce.date().nullish());

/** "true"/"false" (case-insensitive) or "1"/"0" -> boolean. */
const csvBoolean = z.preprocess((val) => {
  if (typeof val === 'boolean') return val;
  if (typeof val === 'string') {
    const v = val.trim().toLowerCase();
    return v === 'true' || v === '1';
  }
  return Boolean(val);
}, z.boolean());

/** "" -> null, otherwise a whole number (rates are rounded to whole dollars). */
const csvNumber = z.preprocess(
  (val) => (val === '' ? null : val),
  z.coerce.number().transform(Math.round).nullish()
);

// --- candidates ----------------------------------------------------------

export const candidateTable = sqliteTable('candidates', {
  id: int().primaryKey({ autoIncrement: true }),
  firstName: text().notNull(),
  lastName: text().notNull(),

  fullTime: int({ mode: 'boolean' }).notNull(),
  fullTimeStartDate: int({ mode: 'timestamp' }),
  /** Expected monthly rate in USD for full-time work. */
  fullTimeMonthlyRate: int(),

  partTime: int({ mode: 'boolean' }).notNull(),
  partTimeStartDate: int({ mode: 'timestamp' }),
  /** Expected monthly rate in USD for part-time work. */
  partTimeMonthlyRate: int(),

  contractor: int({ mode: 'boolean' }).notNull(),
  employee: int({ mode: 'boolean' }).notNull(),
  country: text().notNull(),
  biography: text(),

  // Derived at seed time (see src/lib/derive).
  /** Years of experience, overlaps merged, internships and breaks excluded. */
  yearsExperience: real().notNull().default(0),
  /** Full-time monthly rate if plausible (500-30000 USD), else null. */
  fullTimeRateNormalized: int(),
  /** Part-time monthly rate if plausible (500-30000 USD), else null. */
  partTimeRateNormalized: int(),
  /** true when the full-time rate is missing or implausible. */
  rateUnverified: int({ mode: 'boolean' }).notNull().default(false),
});

export const candidateInsertSchema = z.object({
  firstName: z.string(),
  lastName: z.string(),
  fullTime: csvBoolean,
  fullTimeStartDate: csvDate,
  fullTimeMonthlyRate: csvNumber,
  partTime: csvBoolean,
  partTimeStartDate: csvDate,
  partTimeMonthlyRate: csvNumber,
  contractor: csvBoolean,
  employee: csvBoolean,
  country: z.string(),
  biography: z.string().nullish(),
});

export type Candidate = typeof candidateTable.$inferSelect;
export type CandidateInsert = z.infer<typeof candidateInsertSchema>;

// --- education -----------------------------------------------------------

export const educationTable = sqliteTable('education', {
  id: int().primaryKey({ autoIncrement: true }),
  candidateId: int()
    .references(() => candidateTable.id)
    .notNull(),
  school: text().notNull(),
  degree: text().notNull(),
  startDate: int({ mode: 'timestamp' }),
  endDate: int({ mode: 'timestamp' }),
});

export const educationInsertSchema = z.object({
  candidateId: z.number(),
  school: z.string(),
  degree: z.string(),
  startDate: csvDate,
  endDate: csvDate,
});

export type Education = typeof educationTable.$inferSelect;
export type EducationInsert = z.infer<typeof educationInsertSchema>;

// --- experiences ---------------------------------------------------------

export const experienceTable = sqliteTable('experiences', {
  id: int().primaryKey({ autoIncrement: true }),
  candidateId: int()
    .references(() => candidateTable.id)
    .notNull(),
  company: text().notNull(),
  position: text().notNull(),
  description: text(),
  startDate: int({ mode: 'timestamp' }),
  endDate: int({ mode: 'timestamp' }),
});

export const experienceInsertSchema = z.object({
  candidateId: z.number(),
  company: z.string(),
  position: z.string(),
  description: z.string().default(''),
  startDate: csvDate,
  endDate: csvDate,
});

export type Experience = typeof experienceTable.$inferSelect;
export type ExperienceInsert = z.infer<typeof experienceInsertSchema>;

// --- candidate skills (derived) -------------------------------------------

export const candidateSkillTable = sqliteTable(
  'candidate_skills',
  {
    candidateId: int()
      .references(() => candidateTable.id)
      .notNull(),
    /** Canonical skill name from SKILLS. */
    skill: text().notNull(),
    /** Whether the skill was found in the biography. */
    inBio: int({ mode: 'boolean' }).notNull(),
    /** How many experiences mention it, in position or description. */
    roleCount: int().notNull(),
  },
  (table) => [
    primaryKey({ columns: [table.candidateId, table.skill] }),
    index('candidate_skills_skill_idx').on(table.skill),
  ]
);

export type CandidateSkill = typeof candidateSkillTable.$inferSelect;
export type CandidateSkillInsert = typeof candidateSkillTable.$inferInsert;
/**
 * Seed the local SQLite database from the CSV files in the repo root.
 *
 *   npm run db:seed          # create tables (if needed) and load data once
 *   npm run db:reset         # wipe and reload everything
 *
 * Safe to re-run: if candidates already exist it exits without changes unless
 * `--force` is passed.
 */
import fs from 'node:fs/promises';
import { parse } from 'csv-parse/sync';
import { count, eq, type InferInsertModel, type Table } from 'drizzle-orm';
import { migrate } from 'drizzle-orm/libsql/migrator';
import { z } from 'zod';
import { type JobInput, yearsOfExperience } from '../lib/derive/experience';
import { normalizeMonthlyRate } from '../lib/derive/rate';
import { extractSkills } from '../lib/derive/skills';
import { DATABASE_URL, db } from './index';
import {
  candidateInsertSchema,
  candidateSkillTable,
  candidateTable,
  educationInsertSchema,
  educationTable,
  experienceInsertSchema,
  experienceTable,
} from './schema';

const FORCE = process.argv.includes('--force');
const BATCH_SIZE = 200;

async function main() {
  const startedAt = performance.now();
  console.log(`Database: ${DATABASE_URL}`);

  await step('Applying migrations', () => migrate(db, { migrationsFolder: './migrations' }));

  const [{ existing }] = await db.select({ existing: count() }).from(candidateTable);
  if (existing > 0) {
    if (!FORCE) {
      console.log(`Database already has ${existing} candidates. Nothing to do.`);
      console.log('Run `npm run db:reset` to wipe and reload.');
      return;
    }
    await step('Clearing existing data', async () => {
      await db.delete(candidateSkillTable);
      await db.delete(experienceTable);
      await db.delete(educationTable);
      await db.delete(candidateTable);
    });
  }

  // Candidates -------------------------------------------------------------
  const candidates = await step('Reading candidates.csv', () =>
    loadCsv('candidates.csv', candidateInsertSchema.extend({ userId: z.string() }))
  );

  const candidateIdByUserId = new Map<string, number>();
  await step(`Inserting ${candidates.length} candidates`, async () => {
    for (const batch of chunk(candidates, BATCH_SIZE)) {
      const inserted = await db
        .insert(candidateTable)
        .values(batch.map((c) => candidateInsertSchema.parse(c)))
        .returning({ id: candidateTable.id });
      batch.forEach((c, i) => candidateIdByUserId.set(c.userId, inserted[i].id));
    }
  });

  const resolveCandidateId = (userId: string) => {
    const id = candidateIdByUserId.get(userId);
    if (id === undefined) throw new Error(`Unknown candidate userId ${userId}`);
    return id;
  };

  // Education --------------------------------------------------------------
  const education = await step('Reading education.csv', () =>
    loadCsv(
      'education.csv',
      educationInsertSchema.omit({ candidateId: true }).extend({ userId: z.string() })
    )
  );
  await step(`Inserting ${education.length} education records`, () =>
    insertBatched(
      educationTable,
      education.map(({ userId, ...row }) => ({ ...row, candidateId: resolveCandidateId(userId) }))
    )
  );

  // Experiences ------------------------------------------------------------
  const experiences = await step('Reading experiences.csv', () =>
    loadCsv(
      'experiences.csv',
      experienceInsertSchema.omit({ candidateId: true }).extend({ userId: z.string() })
    )
  );
  await step(`Inserting ${experiences.length} experience records`, () =>
    insertBatched(
      experienceTable,
      experiences.map(({ userId, ...row }) => ({ ...row, candidateId: resolveCandidateId(userId) }))
    )
  );

  // Derived data -----------------------------------------------------------
  const skillRows = await step('Deriving experience, rates and skills', async () => {
    const today = new Date();
    const jobsByCandidate = new Map<number, (JobInput & { description: string })[]>();
    for (const e of experiences) {
      const id = resolveCandidateId(e.userId);
      const jobs = jobsByCandidate.get(id) ?? [];
      jobs.push({ ...e, startDate: e.startDate ?? null, endDate: e.endDate ?? null });
      jobsByCandidate.set(id, jobs);
    }
    const rows: InferInsertModel<typeof candidateSkillTable>[] = [];

    await db.transaction(async (tx) => {
      for (const c of candidates) {
        const candidateId = resolveCandidateId(c.userId);
        const jobs = jobsByCandidate.get(candidateId) ?? [];
        const fullTime = normalizeMonthlyRate(c.fullTimeMonthlyRate ?? null);
        const partTime = normalizeMonthlyRate(c.partTimeMonthlyRate ?? null);

        await tx
          .update(candidateTable)
          .set({
            yearsExperience: yearsOfExperience(jobs, today),
            fullTimeRateNormalized: fullTime.monthlyRate,
            partTimeRateNormalized: partTime.monthlyRate,
            rateUnverified: fullTime.rateUnverified,
          })
          .where(eq(candidateTable.id, candidateId));

        rows.push(...deriveSkills(candidateId, c.biography ?? '', jobs));
      }
    });

    await insertBatched(candidateSkillTable, rows);
    return rows;
  });

  const seconds = ((performance.now() - startedAt) / 1000).toFixed(1);
  console.log(`\nDone in ${seconds}s`);
  console.log(`  candidates:  ${candidates.length}`);
  console.log(`  education:   ${education.length}`);
  console.log(`  experiences: ${experiences.length}`);
  console.log(`  skills:      ${skillRows.length}`);
}

// --- helpers ---------------------------------------------------------------

/** One candidate_skills row per skill found in the bio or any experience. */
function deriveSkills(
  candidateId: number,
  biography: string,
  jobs: { position: string; description: string }[]
): InferInsertModel<typeof candidateSkillTable>[] {
  const inBio = new Set(extractSkills(biography));
  const roleCount = new Map<string, number>();
  for (const job of jobs) {
    for (const skill of extractSkills(`${job.position}\n${job.description}`)) {
      roleCount.set(skill, (roleCount.get(skill) ?? 0) + 1);
    }
  }
  const skills = new Set([...inBio, ...roleCount.keys()]);
  return [...skills].map((skill) => ({
    candidateId,
    skill,
    inBio: inBio.has(skill),
    roleCount: roleCount.get(skill) ?? 0,
  }));
}

async function step<T>(label: string, run: () => Promise<T>): Promise<T> {
  const start = performance.now();
  try {
    const result = await run();
    console.log(`✓ ${label} (${((performance.now() - start) / 1000).toFixed(2)}s)`);
    return result;
  } catch (error) {
    console.error(`✗ ${label}`);
    throw error;
  }
}

function chunk<T>(items: T[], size: number): T[][] {
  const out: T[][] = [];
  for (let i = 0; i < items.length; i += size) out.push(items.slice(i, i + size));
  return out;
}

async function insertBatched<T extends Table>(table: T, rows: InferInsertModel<T>[]) {
  for (const batch of chunk(rows, BATCH_SIZE)) {
    await db.insert(table).values(batch);
  }
}

async function loadCsv<T extends z.ZodType>(path: string, schema: T): Promise<z.infer<T>[]> {
  const raw: Record<string, unknown>[] = parse(await fs.readFile(path), {
    columns: true,
    skip_empty_lines: true,
    bom: true,
  });

  const rows: z.infer<T>[] = [];
  const errors: string[] = [];
  raw.forEach((record, index) => {
    const result = schema.safeParse(record);
    if (result.success) rows.push(result.data);
    else errors.push(`  row ${index + 2}: ${result.error.message}`); // +2: header + 1-based
  });

  if (errors.length > 0) {
    throw new Error(`${errors.length} invalid rows in ${path}:\n${errors.slice(0, 10).join('\n')}`);
  }
  return rows;
}

main().catch((error) => {
  console.error('\nSeed failed:', error);
  process.exit(1);
});
import { drizzle } from 'drizzle-orm/libsql';
import * as schema from './schema';

/** Path to the SQLite file. Created and populated by `npm run db:seed`. */
export const DATABASE_URL = 'file:local.db';

/** Shared database client. */
export const db = drizzle({
  connection: { url: DATABASE_URL },
  casing: 'snake_case',
  schema,
});

export type Db = typeof db;
import OpenAI from 'openai';

/**
 * OpenAI client and model defaults.
 *
 * Set OPENAI_API_KEY in `.env` (see `.env.example`). You are free to change the
 * models below or swap in another provider or a local embedding model.
 */

export const EMBEDDING_MODEL = 'text-embedding-3-small';
export const CHAT_MODEL = 'gpt-4o-mini';

let client: OpenAI | null = null;

export function getOpenAI(): OpenAI {
  const apiKey = process.env.OPENAI_API_KEY;
  if (!apiKey || apiKey.includes('REPLACE_ME')) {
    throw new Error('OPENAI_API_KEY is not set. Copy .env.example to .env and add your real key.');
  }
  client ??= new OpenAI({ apiKey });
  return client;
}

/** Embed one or more strings. Returns one vector per input, in order. */
export async function embed(input: string[]): Promise<number[][]> {
  if (input.length === 0) return [];
  const response = await getOpenAI().embeddings.create({ model: EMBEDDING_MODEL, input });
  return response.data.map((d) => d.embedding);
}
import { defineConfig } from 'drizzle-kit';

export default defineConfig({
  schema: './src/db/schema.ts',
  out: './migrations',
  dialect: 'sqlite',
  dbCredentials: {
    url: 'file:local.db',
  },
  casing: 'snake_case',
});
