86	/** Resume document per candidate id, built from bio, experiences and education. */
87	async function loadResumeDocuments(): Promise<Map<number, string>> {
88	  const [candidates, experiences, education] = await Promise.all([
89	    db
90	      .select({ id: candidateTable.id, biography: candidateTable.biography })
91	      .from(candidateTable)
92	      .orderBy(asc(candidateTable.id)),
93	    db.select().from(experienceTable).orderBy(asc(experienceTable.id)),
94	    db.select().from(educationTable).orderBy(asc(educationTable.id)),
95	  ]);
96	
97	  const parts = new Map<number, ResumeParts>(
98	    candidates.map((c) => [c.id, { biography: c.biography ?? '', experiences: [], education: [] }])
99	  );
100	  for (const e of experiences) {
101	    parts.get(e.candidateId)?.experiences.push({
102	      position: e.position,
103	      company: e.company,
104	      description: e.description ?? '',
105	    });
106	  }
107	  for (const e of education) {
108	    parts.get(e.candidateId)?.education.push({ degree: e.degree, school: e.school });
109	  }
110	
111	  return new Map([...parts].map(([id, p]) => [id, buildResumeDocument(p)]));
112	}
