const W = '/home/rk/Projects/Dev/oremono/crew-interview-challenge-rishab-kohale/.claude/worktrees/agent-aa7c61951351c38f3';

async function main() {
  const { buildResumeDocument } = await import(`${W}/src/lib/search/document.ts`);
  const { toFtsQuery, keywordSearch } = await import(`${W}/src/lib/search/keyword.ts`);
  const { semanticSearch } = await import(`${W}/src/lib/search/semantic.ts`);
  const { db } = await import(`${W}/src/db/index.ts`);
  const { sql } = await import('drizzle-orm');

  const ok = (n: number, cond: boolean, got: unknown) =>
    console.log(`${cond ? 'PASS' : 'FAIL'} ${n}`, cond ? '' : JSON.stringify(got));
  const exp = { position: 'Engineer', company: 'Acme', description: 'Built APIs' };
  const edu = { degree: 'BSc CS', school: 'MIT' };

  let d = buildResumeDocument({ biography: 'Rust dev', experiences: [exp], education: [edu] });
  ok(1, d === 'Rust dev\n\nExperience:\n- Engineer at Acme: Built APIs\n\nEducation:\n- BSc CS, MIT', d);
  d = buildResumeDocument({ biography: 'x', experiences: [{ ...exp, description: '' }], education: [] });
  ok(2, d.split('\n').includes('- Engineer at Acme'), d);
  d = buildResumeDocument({ biography: 'x', experiences: [], education: [{ degree: ' ', school: 'MIT' }] });
  ok(3, d.split('\n').includes('- MIT'), d);
  d = buildResumeDocument({ biography: 'Rust dev', experiences: [], education: [] });
  ok(4, d === 'Rust dev', d);
  d = buildResumeDocument({ biography: '', experiences: [exp], education: [] });
  ok(5, d.startsWith('Experience:'), d);
  d = buildResumeDocument({ biography: 'a'.repeat(10000), experiences: [], education: [] });
  ok(6, d.length === 6000, d.length);

  const q: [number, string, string | null][] = [
    [7, 'Rust', '"rust"'],
    [8, 'AI/ML engineer', '"ai" OR "ml" OR "engineer"'],
    [9, 'C++ and C#', '"c++" OR "and" OR "c#"'],
    [10, 'node.js.', '"node.js"'],
    [11, 'NOT rust', '"not" OR "rust"'],
    [12, 'rust Rust RUST', '"rust"'],
  ];
  for (const [n, input, want] of q) ok(n, toFtsQuery(input) === want, toFtsQuery(input));
  const nulls = ['', '   ', 'a', '"; --'].map(toFtsQuery);
  ok(13, nulls.every((x) => x === null), nulls);

  const rust = await keywordSearch('rust');
  ok(
    14,
    rust.length >= 5 &&
      rust.every((h: { snippet: string; score: number }) => h.snippet.includes('⟪') && h.score > 0) &&
      rust.every((h: { score: number }, i: number) => i === 0 || rust[i - 1].score >= h.score),
    rust.slice(0, 3)
  );
  console.log('   rust hits:', rust.length, 'top:', JSON.stringify(rust[0]));
  ok(15, (await keywordSearch('zzzqqqxx')).length === 0, null);
  ok(16, (await keywordSearch('')).length === 0, null);
  const py = await keywordSearch('python', { limit: 3 });
  ok(17, py.length === 3, py);
  const ids = py.slice(0, 2).map((h: { candidateId: number }) => h.candidateId);
  const py2 = await keywordSearch('python', { candidateIds: ids });
  ok(18, py2.length === 2 && py2.every((h: { candidateId: number }) => ids.includes(h.candidateId)), py2);
  ok(18.1, (await keywordSearch('python', { candidateIds: [] })).length === 0, null);
  const [{ n }] = await db.all(sql`SELECT count(*) AS n FROM candidate_search`);
  ok(19, n === 1000, n);

  const models = await db.all(sql`SELECT model, count(*) AS n FROM candidate_embeddings GROUP BY model`);
  ok(20, models.length === 1 && models[0].model === 'text-embedding-3-small' && models[0].n === 1000, models);
  const [row] = await db.all(
    sql`SELECT candidate_id AS id, vector_extract(embedding) AS v FROM candidate_embeddings WHERE candidate_id = 123`
  );
  const vec = JSON.parse(row.v);
  const sem = await semanticSearch(vec);
  ok(
    21,
    sem[0].candidateId === 123 &&
      sem[0].similarity > 0.999 &&
      sem.every((h: { similarity: number }, i: number) => i === 0 || sem[i - 1].similarity >= h.similarity),
    sem.slice(0, 3)
  );
  console.log('   sem len', sem.length, 'top:', JSON.stringify(sem.slice(0, 2)));
  ok(22, (await semanticSearch(vec, { limit: 5 })).length === 5, null);
  ok(22.1, (await semanticSearch(vec, { candidateIds: [] })).length === 0, null);
  const semIds = await semanticSearch(vec, { candidateIds: [5, 123, 7], limit: 2 });
  ok(22.2, semIds.length === 2 && semIds[0].candidateId === 123, semIds);
  // Drizzle customType round trip
  const { candidateEmbeddingTable } = await import(`${W}/src/db/schema.ts`);
  const [e] = await db.select().from(candidateEmbeddingTable).limit(1);
  console.log('   customType read: len', e.embedding.length, typeof e.embedding[0]);
}
main();

